class ParseFailure(Exception):
    def __init__(self, message, end):
        self.message = message
        self.end = end


def expected_list(values):
    vals = ['`'+x+'`' for x in values]
    if not vals: return 'no fields'
    if len(vals) == 1: return vals[0]
    if len(vals) == 2: return vals[0]+' or '+vals[1]
    return 'one of '+', '.join(vals)


def type_description(value):
    if value is None: return 'null'
    if isinstance(value, bool): return 'boolean `'+str(value).lower()+'`'
    if isinstance(value, int): return 'integer `'+str(value)+'`'
    if isinstance(value, float): return 'floating point `'+str(value)+'`'
    if isinstance(value, str): return 'string '+json.dumps(value, ensure_ascii=False)
    if isinstance(value, list): return 'sequence'
    return 'map'


class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def fail(self, msg, end=None):
        raise ParseFailure(msg, self.pos if end is None else end)

    def ws(self):
        while self.pos < len(self.text) and self.text[self.pos] in ' \r\t\n': self.pos += 1

    def peek(self):
        self.ws()
        return self.text[self.pos:self.pos+1]

    def string(self):
        if self.pos >= len(self.text) or self.text[self.pos] != '"':
            self.fail('key must be a string', self.pos+1)
        start = self.pos
        self.pos += 1
        while self.pos < len(self.text):
            c = self.text[self.pos]
            self.pos += 1
            if c == '"':
                try: return json.loads(self.text[start:self.pos])
                except (ValueError, UnicodeError): self.fail('invalid escape')
            if ord(c) < 32:
                self.fail('control character (\\u0000-\\u001F) found while parsing a string')
            if c == '\\':
                if self.pos == len(self.text): self.fail('EOF while parsing a string')
                e = self.text[self.pos]
                self.pos += 1
                if e == 'u':
                    for _ in range(4):
                        if self.pos == len(self.text): self.fail('EOF while parsing a string')
                        h = self.text[self.pos]; self.pos += 1
                        if h not in '0123456789abcdefABCDEF': self.fail('invalid escape')
                elif e not in '"\\/bfnrt': self.fail('invalid escape')
        self.fail('EOF while parsing a string')

    def number(self):
        start = self.pos
        n = len(self.text)
        if self.text[self.pos] == '-':
            self.pos += 1
            if self.pos == n: self.fail('EOF while parsing a value')
        if self.text[self.pos:self.pos+1] == '0':
            self.pos += 1
            if self.pos < n and self.text[self.pos].isdigit(): self.fail('invalid number',self.pos+1)
        elif self.pos < n and self.text[self.pos] in '123456789':
            while self.pos < n and self.text[self.pos].isdigit(): self.pos += 1
        else: self.fail('invalid number',self.pos+1)
        if self.pos < n and self.text[self.pos] == '.':
            self.pos += 1
            if self.pos == n: self.fail('EOF while parsing a value')
            if not self.text[self.pos].isdigit(): self.fail('invalid number', self.pos+1)
            while self.pos < n and self.text[self.pos].isdigit(): self.pos += 1
        if self.pos < n and self.text[self.pos] in 'eE':
            self.pos += 1
            if self.pos < n and self.text[self.pos] in '+-': self.pos += 1
            if self.pos == n: self.fail('EOF while parsing a value')
            if not self.text[self.pos].isdigit(): self.fail('invalid number',self.pos+1)
            while self.pos < n and self.text[self.pos].isdigit(): self.pos += 1
        num = json.loads(self.text[start:self.pos])
        if isinstance(num,float) and not math.isfinite(num): self.fail('number out of range')
        return num

    def atom(self):
        c = self.peek()
        if not c: self.fail('EOF while parsing a value')
        if c == '"': return self.string()
        if c in '-0123456789': return self.number()
        for literal, value in [('null',None),('true',True),('false',False)]:
            if c == literal[0]:
                for ch in literal:
                    if self.pos == len(self.text): self.fail('EOF while parsing a value')
                    actual = self.text[self.pos]; self.pos += 1
                    if actual != ch: self.fail('expected ident')
                return value
        self.fail('expected value', self.pos+1)

    def expect_type(self, schema):
        if schema == S: return 'a string'
        if schema == B: return 'a boolean'
        if schema == 'unit': return 'unit'
        kind = schema[0]
        if kind == 'struct': return 'struct '+schema[1]
        if kind == 'sequence': return 'a sequence'
        if kind == 'map': return 'a map'
        if kind == 'enum': return 'string or map'
        return 'a value'

    def mismatch(self, schema):
        c = self.peek()
        if c == '{':
            self.pos += 1; desc = 'map'
        elif c == '[':
            self.pos += 1; desc = 'sequence'
        else: desc = type_description(self.atom())
        self.fail('invalid type: '+desc+', expected '+self.expect_type(schema))

    def read(self, schema='any'):
        c = self.peek()
        if not c: self.fail('EOF while parsing a value')
        if isinstance(schema,tuple) and schema[0] == 'optional':
            if c == 'n':
                value = self.atom()
                if value is None: return None
            return self.read(schema[1])
        if schema == 'any':
            if c == '{': return self.object(mapping('any'))
            if c == '[': return self.array(sequence('any'))
            return self.atom()
        if schema == S:
            if c == '"': return self.string()
            self.mismatch(schema)
        if schema == B:
            if c in 'tf': return self.atom()
            self.mismatch(schema)
        if schema == 'unit':
            if c == 'n': return self.atom()
            self.mismatch(schema)
        kind = schema[0]
        if kind == 'boolor':
            start = self.pos
            value = self.read('any')
            end = self.pos
            if isinstance(value,bool): return value
            valid = isinstance(value,dict)
            if valid:
                parser = Parser(self.text[start:end])
                try:
                    value = parser.read(schema[1])
                except ParseFailure:
                    valid = False
            if valid: return value
            self.ws()
            self.fail('data did not match any variant of untagged enum BoolOr', min(len(self.text),self.pos+1))
        if kind in ('struct','map'):
            if c == '{': return self.object(schema)
            if kind == 'struct' and c == '[': return self.array(schema)
            self.mismatch(schema)
        if kind == 'sequence':
            if c == '[': return self.array(schema)
            self.mismatch(schema)
        if kind == 'enum': return self.enumeration(schema)
        return self.read('any')

    def object(self, schema):
        self.pos += 1
        struct = schema[0] == 'struct'
        fields = schema[2] if struct else None
        result = {}
        c = self.peek()
        if not c: self.fail('EOF while parsing an object')
        if c != '}':
            while True:
                if self.peek() != '"':
                    if not self.peek(): self.fail('EOF while parsing an object')
                    self.fail('key must be a string',self.pos+1)
                key = self.string()
                if struct:
                    if key in fields:
                        if key in result and result[key] is not None:
                            self.fail('duplicate field `'+key+'`')
                        field_schema = fields[key]
                    elif schema[4]: field_schema = 'any'
                    else: self.fail('unknown field `'+key+'`, expected '+expected_list(fields))
                else: field_schema = schema[1]
                c = self.peek()
                if not c: self.fail('EOF while parsing an object')
                if c != ':': self.fail('expected `:`',self.pos+1)
                self.pos += 1
                result[key] = self.read(field_schema)
                c = self.peek()
                if c == '}': break
                if not c: self.fail('EOF while parsing an object')
                if c != ',': self.fail('expected `,` or `}`',self.pos+1)
                self.pos += 1
                if self.peek() == '}': self.fail('trailing comma',self.pos+1)
        self.pos += 1
        if struct:
            for k in fields:
                if k in schema[3] and k not in result:
                    self.fail('missing field `'+k+'`')
        return result

    def array(self,schema):
        self.pos += 1
        result = []
        struct = schema[0] == 'struct'
        fields = list(schema[2].items()) if struct else []
        if self.peek() != ']':
            while True:
                if not self.peek(): self.fail('EOF while parsing a list')
                if struct:
                    if len(result) >= len(fields):
                        self.fail('invalid length '+str(len(result)+1)+', expected fewer elements in array', self.pos+1)
                    sub = fields[len(result)][1]
                else: sub = schema[1]
                result.append(self.read(sub))
                c = self.peek()
                if c == ']': break
                if not c: self.fail('EOF while parsing a list')
                if c != ',': self.fail('expected `,` or `]`',self.pos+1)
                self.pos += 1
                if self.peek() == ']': self.fail('trailing comma',self.pos+1)
        self.pos += 1
        if struct:
            if len(result) < len(fields):
                self.fail(f'invalid length {len(result)}, expected struct {schema[1]} with {len(fields)} elements')
            return {key:value for (key,_),value in zip(fields,result)}
        return result

    def enumeration(self,schema):
        values = schema[2]
        c = self.peek()
        object_variant = c == '{'
        if object_variant:
            self.pos += 1
            c = self.peek()
            if c != '"':
                if c == '}': self.pos+=1
                self.fail('expected value',self.pos+1 if c != '}' else None)
            variant = self.string()
        elif c == '"': variant = self.string()
        else: self.mismatch(schema)
        if variant not in values:
            self.fail('unknown variant `'+variant+'`, expected '+expected_list(values))
        sub = values[variant]
        if not object_variant:
            if sub is not None: self.fail('invalid type: unit variant, expected newtype variant')
            return variant
        if self.peek() != ':': self.fail('expected `:`',self.pos+1)
        self.pos += 1
        value = self.read(sub if sub is not None else 'unit')
        if self.peek() != '}': self.fail('expected `}`',self.pos+1)
        self.pos += 1
        return {variant:value} if sub is not None else variant

    def finish(self,schema=CONFIG):
        result = self.read(schema)
        if self.peek(): self.fail('trailing characters',self.pos+1)
        return result


def parse(text,filename='./oranda.json',schema=CONFIG):
    parser = Parser(text)
    try:
        return parser.finish(schema)
    except ParseFailure as e:
        before = text[:max(0,e.end)]
        line = before.count('\n')+1
        col = len(before.rsplit('\n',1)[-1].encode('utf-8'))
        offset = max(0,len(before.encode('utf-8'))-1)
        cause = f'{e.message} at line {line} column {col}'
        raise Diagnostic('failed to parse JSON', [cause], source=text,
                         filename=filename, offset=offset if text else None)


def nonnull_dict(value):
    return {k:v for k,v in value.items() if v is not None} if isinstance(value,dict) else {}


def merge(base, layer):
    for key,value in layer.items():
        if value is None: continue
        if isinstance(value,dict) and isinstance(base.get(key),dict): merge(base[key],value)
        else: base[key] = value
    return base


