def nonnull_dict(value):
    return {k:v for k,v in value.items() if v is not None} if isinstance(value,dict) else {}


def merge(base, layer):
    for key,value in layer.items():
        if value is None: continue
        if isinstance(value,dict) and isinstance(base.get(key),dict): merge(base[key],value)
        else: base[key] = value
    return base


