        result=execute(command,opts)
        sys.exit(result or 0)
    except CLIExit as e:
        sys.exit(e.code)
    except diag.Diagnostic as e:
        e.emit(fatal=True)
        sys.exit(255)
    except KeyboardInterrupt:
        sys.exit(130)
    except BrokenPipeError:
