"""Read local project metadata and apply the site's configuration layers."""
import json
import os
from pathlib import Path
import re
import subprocess
import shutil
import diagnostics as diag
import config


def warning_for(kind, filename, causes):
    diag.Diagnostic(f'We found a potential {kind} project at {filename} but there was an issue',
                    causes, severity='warning').emit()


def find_manifest(name):
    path=Path.cwd()
    while True:
        if (path/name).is_file(): return path/name
        if (path/'.git').exists(): return None
        if path.parent==path: return None
        path=path.parent


def cargo_project(path):
    try:
        proc=subprocess.run(['cargo','metadata','--format-version','1','--no-deps'],
                cwd=str(path.parent), stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    except OSError:
        return None
    if proc.returncode:
        warning_for('rust',str(path), ['  × `cargo metadata` execution failed\n',
                                      '`cargo metadata` exited with an error: '+proc.stderr])
        return None
    try: metadata=json.loads(proc.stdout)
    except ValueError: return None
    packages=metadata.get('packages',[])
    root=None
    for package in packages:
        if os.path.abspath(package.get('manifest_path',''))==os.path.abspath(path):
            root=package;break
    if root is None: return {}
    result={}
    for field in ['name','version','description','homepage','repository','license']:
        if root.get(field) is not None: result[field]=root[field]
    readme=root.get('readme')
    if readme:
        result['readme_path']=str(path.parent/readme)
    elif (path.parent/'README.md').is_file():
        result['readme_path']=str(path.parent/'README.md')
    return result


def _npm_diagnostic(text,filename,detail,end):
    prefix=text[:end]
    line=prefix.count('\n')+1
    column=len(prefix.rsplit('\n',1)[-1].encode())
    d=diag.Diagnostic('failed to parse JSON',source=text,filename=filename,
                       offset=max(0,len(prefix.encode())-1) if end else None)
    warning_for('javascript',filename,[d.human().rstrip('\n')+'\n',f'{detail} at line {line} column {column}'])


def npm_project(path):
    try: text=path.read_text()
    except (OSError,UnicodeError): return None
    # Most npm fields are optional, and unknown package properties are metadata.
    schema=config.structure('Manifest', {name:config.optional(config.S) for name in
        ['name','description','homepage','readme']}, unknown=True)
    try:
        data=config.parse(text,str(path),schema)
    except diag.Diagnostic as d:
        without_causes=diag.Diagnostic(d.message,source=d.source,filename=d.filename,offset=d.offset)
        warning_for('javascript',str(path),[without_causes.human().rstrip('\n')+'\n']+d.causes)
        return None
    if not isinstance(data,dict): return None
    version=data.get('version')
    if version is not None:
        if not isinstance(version,str) or not re.fullmatch(r'\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?', version):
            why=('Failed to parse version.' if isinstance(version,str) else
                 'invalid type: '+config.type_description(version)+', expected a version string')
            _npm_diagnostic(text,str(path),why,len(text.rstrip()))
            return None
    repository=data.get('repository')
    if repository is not None:
        if not isinstance(repository,(str,dict)) or (isinstance(repository,dict) and
                any(repository.get(k) is not None and not isinstance(repository[k],str) for k in ('url','type','directory'))):
            _npm_diagnostic(text,str(path),'data did not match any variant of untagged enum Repository',len(text.rstrip())+1)
            return None
    if data.get('name') is None:
        d=diag.Diagnostic("your package doesn't have a name: "+str(path),
                           help="is it a workspace? We don't support that yet.")
        warning_for('javascript',str(path),[d.human().rstrip('\n')+'\n'])
        return None
    result={k:data[k] for k in ['name','version','description','homepage'] if data.get(k) is not None}
    if isinstance(repository,dict) and isinstance(repository.get('url'),str):
        result['repository']=repository['url']
    # The discovery layer resolves the README adjacent to the manifest.
    for filename in ['README.md','README','readme.md','Readme.md','README.markdown']:
        if (path.parent/filename).is_file():
            result['readme_path']=str(path.parent/filename);break
    return result


def discover():
    cargo=find_manifest('Cargo.toml')
    npm=find_manifest('package.json')
    if cargo:
        result=cargo_project(cargo)
        if result is not None: return result
    if npm:
        result=npm_project(npm)
        if result is not None: return result
    return {'readme_path':'README.md'} if os.path.exists('README.md') else {}


def read_config(opts):
    filename=opts.get('config-path','./oranda.json')
    layer={}
    if os.path.isfile(filename):
        try:
            with open(filename,'r',encoding='utf-8') as f: text=f.read()
        except OSError as e: raise diag.os_error(e)
        except UnicodeError:
            raise diag.Diagnostic('stream did not contain valid UTF-8')
        layer=config.parse(text,filename)
    else:
        diag.log('DEBUG','No config found, using default values')
    cfg=config.defaults()
    cfg['project'].update(discover())
    config.merge(cfg,layer)
    components=cfg['components']
    book=components.get('mdbook')
    if isinstance(book,dict) and book.get('theme') is False and book.get('path') is None:
        candidates=['book.toml','docs/book.toml']
        if not any(os.path.exists(p) for p in candidates):
            raise diag.Diagnostic("Couldn't find your book.toml",
                                  help='You can manually specify path in your components.mdbook config')
    funding=components.get('funding')
    if isinstance(funding,dict) and funding.get('preferred_funding') is not None and not any(funding.get(k) is not None for k in ['md_path','yml_path']):
        candidates=['.github/FUNDING.yml','FUNDING.yml','funding.md']
        if not any(os.path.exists(p) for p in candidates):
            raise diag.Diagnostic("Couldn't find your FUNDING.yml or funding.md",
                help='You can manually specify md_path or yml_path in your components.funding config')
    return cfg
