def make_server(cfg,port):
    dist=cfg['build']['dist_dir']
    if not os.path.isdir(dist or '.'): raise build_not_found(dist)
    try:
        server=Server(('127.0.0.1',port),FileHandler)
    except OSError as e:
        msg='Address already in use (os error 98)' if e.errno==98 else (e.strerror+f' (os error {e.errno})')
        raise diag.panic('/usr/local/cargo/registry/src/index.crates.io-6f17d22bba15001f/hyper-0.14.28/src/server/server.rs:81:13',
            f'error binding to 127.0.0.1:{port}: error creating server listener: '+msg)
    server.site_dir=os.path.abspath(dist or '.')
    server.site_prefix=cfg['build']['path_prefix']
    return server


def serve(opts):
    cfg=project.read_config(opts)
    dist=cfg['build']['dist_dir']
    if not os.path.isdir(dist or '.'): raise build_not_found(dist)
    port=opts.get('port',7979)
    diag.log('SUCCESS',f'Your project is available at: http://127.0.0.1:{port}/'+cfg['build']['path_prefix'])
    server=make_server(cfg,port)
    try: server.serve_forever()
    finally: server.server_close()


def watch_paths(cfg,opts):
    paths=[]
    readme=cfg['project'].get('readme_path')
    if readme and os.path.exists(readme): paths.append(readme)
    if os.path.exists('oranda.json'): paths.append('oranda.json')
    book=cfg['components'].get('mdbook',True)
    if book is not False:
        bookpath=book.get('path') if isinstance(book,dict) else None
        if not bookpath:
            bookpath=next((p for p in ['book.toml','docs/book.toml'] if os.path.exists(p)),None)
        if bookpath and os.path.exists(bookpath):
            root=bookpath if os.path.isdir(bookpath) else os.path.dirname(bookpath)
            tomlfile=os.path.join(root,'book.toml')
            if os.path.isfile(tomlfile): paths.append(tomlfile)
            booksrc=os.path.join(root,'src')
            if os.path.exists(booksrc): paths.append(booksrc)
    for title,path in sorted(cfg['build'].get('additional_pages',{}).items()):
        if not os.path.exists(path):
            raise diag.Diagnostic(f'Specified path `{path}` was not found on your filesystem!',
                help='Make sure you specify your path relative to the oranda.json/manifest file/README file of your project!')
        paths.append(path)
    for path in opts.get('include-paths',[]):
        if os.path.exists(path): paths.append(path)
    return paths


def dev(opts):
    cfg=project.read_config(opts)
    paths=watch_paths(cfg,opts)
    diag.log('INFO',f'Found {len(paths)} paths to watch, starting watch...')
    diag.log('DEBUG','Files watched: '+json.dumps(paths,ensure_ascii=False))
    if not opts.get('no-first-build'): build(opts)
    port=opts.get('port',7979)
    diag.log('SUCCESS',f'Your project is available at: http://127.0.0.1:{port}')
    try:
        server=make_server(cfg,port)
    except diag.Diagnostic as e:
        if e.message.startswith('Could not find a build'):
            dist=json.dumps(cfg['build']['dist_dir'],ensure_ascii=False)
            e=diag.panic('src/commands/dev.rs:131:62',
                'called `Result::unwrap()` on an `Err` value: BuildNotFound { dist_dir: '+dist+' }')
        e.emit()
        server=None
    if server:
        threading.Thread(target=server.serve_forever,daemon=True).start()
    snapshot={p:os.stat(p).st_mtime_ns for p in paths if os.path.exists(p)}
    while True:
        time.sleep(.25)
        updated={p:os.stat(p).st_mtime_ns for p in paths if os.path.exists(p)}
        if updated != snapshot:
            snapshot=updated
            try: build(opts)
            except diag.Diagnostic as e: e.emit()


def generate(opts):
    diag.log('INFO','Generating a CI deploy workflow for your site...')
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        raise diag.panic('src/generate.rs:56:14','Error while prompting!: NotTTY')
    from generation import generate_ci
    generate_ci(opts)


def execute(command,opts):
    if command==('build',): return build(opts)
    if command==('serve',): return serve(opts)
    if command==('dev',): return dev(opts)
    if command==('generate','ci'): return generate(opts)
