        tail=path[len(prefix):]
        if self.server.site_prefix and not self.server.site_prefix.endswith('/') and tail and not tail.startswith('/'):
            return self.empty_response(404)
        tail=tail.lstrip('/')
        if '..' in tail.split('/') or '\x00' in tail: return self.empty_response(404)
        filename=os.path.join(self.server.site_dir,tail)
        if os.path.isdir(filename): filename=os.path.join(filename,'index.html')
        if not os.path.isfile(filename): return self.empty_response(404)
        try:
            st=os.stat(filename)
            with open(filename,'rb') as f: data=f.read()
        except OSError: return self.empty_response(404)
        modified=email.utils.formatdate(st.st_mtime,usegmt=True)
        if self.headers.get('If-Modified-Since'):
            try:
                stamp=email.utils.parsedate_to_datetime(self.headers['If-Modified-Since']).timestamp()
                if int(st.st_mtime)<=stamp: return self.empty_response(304,[('last-modified',modified)])
            except (ValueError,TypeError,OverflowError): pass
        mime=mimetypes.guess_type(filename)[0] or 'application/octet-stream'
        overrides={'.js':'application/javascript','.ico':'image/x-icon','.md':'text/markdown',
                   '.toml':'text/x-toml','.wasm':'application/wasm'}
        mime=overrides.get(os.path.splitext(filename)[1].lower(),mime)
        code=200;length=len(data);start=0;end=length-1
        r=self.headers.get('Range')
        if r:
            m=re.fullmatch(r'bytes=(\d*)-(\d*)',r)
            if m:
                try:
                    if not m[1]: start=max(0,length-int(m[2]))
                    else: start=int(m[1])
                    end=min(end,int(m[2])) if m[1] and m[2] else end
                    if start>=length or end<start: return self.empty_response(416,[('content-range',f'bytes */{length}')])
                    code=206;data=data[start:end+1]
                except ValueError: pass
        self.send_response_only(code)
        self.send_header('content-type',mime)
        self.send_header('accept-ranges','bytes')
        self.send_header('content-encoding','identity')
        self.send_header('last-modified',modified)
        if code==206: self.send_header('content-range',f'bytes {start}-{end}/{length}')
        self.send_header('content-length',str(len(data)))
        self.send_header('date',email.utils.formatdate(usegmt=True))
