"""Interactive infrastructure-file generation."""
import os
import sys
import diagnostics as diag
from templates import WORKFLOW


def confirm(question,default,helptext=None):
    while True:
        sys.stdout.write('? >o_o< '+question+(' (Y/n) ' if default else ' (y/N) '))
        sys.stdout.flush()
        reply=sys.stdin.readline()
        if not reply:
            raise diag.panic('src/generate.rs:56:14','Error while prompting!: OperationCanceled')
        reply=reply.strip().lower()
        if not reply: return default
        if reply in ('y','yes'): return True
        if reply in ('n','no'): return False


def generate_ci(opts):
    links=confirm('Do you want to include a tool for checking generated hyperlinks?',True)
    latest=confirm('Do you want to always use the latest version of oranda?',False)
    ignore=confirm('Would you like to append the default destination directory (`public`) to your .gitignore file?',False)
    text=WORKFLOW
    if latest:
        text=text.replace('releases/download/v0.6.1/oranda-installer.sh','releases/latest/download/oranda-installer.sh')
    if opts.get('site-path') is not None:
        text=text.replace('          oranda build','          cd '+opts['site-path']+'\n          oranda build')
    if not links:
        start=text.index('      - name: Prepare HTML for link checking')
        end=text.index('      # Deploy to our gh-pages',start)
        text=text[:start]+text[end:]
    try:
        if ignore:
            with open('.gitignore','a') as f:
                f.write('\n# Generated by `oranda generate ci`\npublic/')
        output=opts.get('output-path','.github/workflows/web.yml')
        parent=os.path.dirname(output)
        if parent: os.makedirs(parent,exist_ok=True)
        with open(output,'w') as f: f.write(text)
    except OSError as e: raise diag.os_error(e)
    diag.log('SUCCESS','Wrote CI file to "'+output+'"')
